func:
/**
 * Build the user-facing notification text based on the event type.
 *
 * Check if entry id already triggered attatchment notification (otherwise Wasos would recieve notification for each connected log)
 * Each message type provides specific, actionable guidance
 * to help the sender resolve the file transfer issue.
 */


const event = msg.payload;
const entry_id = event.entry_id;
let text;

if (entry_id) {
    const notified = flow.get("_notified_attachments") || {};
    const key = entry_id + "_" + event.type;

    if (notified[key]) {
        return null; // Already notified for this entry
    }

    notified[key] = true;
    flow.set("_notified_attachments", notified);
}

switch (event.type) {
    case "non_transferable":
        text = "⚠️ " + event.file_count + " vedlagte fil(er) kan ikke overføres automatisk. "
             + "Tips: Høyreklikk på bildet → «Kopier bildeadresse» "
             + "→ lim inn adressen som tekst.";
        break;

    case "oversized_files":
        text = "⚠️ " + event.file_names.length + " vedlegg for store for mottakersystemet: "
             + event.file_names.join(", ") + ". "
             + "Maks filstørrelse er ca. 1 MB. Prøv å komprimere eller dele opp filene.";
        break;

    case "upload_failed":
        text = "⚠️ " + event.file_names.length + " av " + event.total_files
             + " vedlegg ble avvist av mottakersystemet: "
             + event.file_names.join(", ") + ".";
        if (event.succeeded > 0) {
            text += " " + event.succeeded + " vedlegg ble levert.";
        }
        break;

    default:
        node.warn("Unknown attachment notification type: " + event.type);
        text = "⚠️ Det oppstod en feil med vedleggshåndtering.";
}

msg._notification_text = text;
msg._event = event;

return msg;

/**
 * Wrap the notification text in a bridge entry format
 * that can be sent through the queue to the sender's system.
 *
 * The entry is addressed FROM parat_bridge TO the sender.
 * This means it goes to the same system the sender used,
 * so they see the notification in their own interface.
 *
 * client_system is set to 'parat_bridge' so the Filter subflow
 * recognises and drops it when polled back, preventing loops.
 *
 * Returns a clean object — no inherited properties.
 */
const event    = msg._event;
const metadata = event.metadata;
const now      = Date.now();

return {
    topic: "new_message",
    entry: {
        id:        "pb-att-" + now + "-" + Math.random().toString(36).substr(2, 6),
        text:      msg._notification_text,
        timestamp: now,
        author:    "System-melding",
        files:     [],
        labels:    [],
        metadata: {
            source: {
                client_system: "parat_bridge",
                name:          "parat_bridge",
                identifier:    "parat_bridge"
            },
            target:          metadata.source,
            connection_name: metadata.connection_name
        }
    }
};
